sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var defaultModel = gs.getProperty('x_146833_claudec_0.model', 'claude-sonnet-5');
    var defaultMaxTokens = parseInt(gs.getProperty('x_146833_claudec_0.max_tokens', '4096'), 10);

    var models = [
        {
            id:           'claude-sonnet-5',
            display_name: 'Claude Sonnet 5',
            description:  'Latest Sonnet model — best balance of intelligence and speed.',
            context_window: 200000,
            max_output_tokens: 64000,
            recommended_for: ['chat', 'code', 'analysis']
        },
        {
            id:           'claude-opus-4-8',
            display_name: 'Claude Opus 4.8',
            description:  'Most capable model — best for complex multi-step reasoning tasks.',
            context_window: 200000,
            max_output_tokens: 32000,
            recommended_for: ['deep reasoning', 'research', 'long-form writing']
        },
        {
            id:           'claude-haiku-4-5',
            display_name: 'Claude Haiku 4.5',
            description:  'Fastest and most compact model — best for high-volume, low-latency tasks.',
            context_window: 200000,
            max_output_tokens: 8096,
            recommended_for: ['classification', 'summarisation', 'quick lookups']
        }
    ];

    response.setStatus(200);
    response.setBody({
        default_model:      defaultModel,
        default_max_tokens: defaultMaxTokens,
        models:             models
    });

})(request, response);
